ALTER TABLE public.sales_leads ADD COLUMN prospect_name text NOT NULL DEFAULT '', ADD COLUMN phone text NOT NULL DEFAULT '', ADD COLUMN address text NOT NULL DEFAULT '', ADD COLUMN source text NOT NULL DEFAULT 'Day-to-day', ADD COLUMN lead_value numeric NOT NULL DEFAULT 0 CHECK (lead_value >= 0), ADD COLUMN verified_by uuid, ADD COLUMN verified_at timestamptz;
ALTER TABLE public.sales_activities ADD COLUMN lead_id uuid REFERENCES public.sales_leads(id);
ALTER POLICY project_read ON public.sales_projects USING (EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id=auth.uid() AND (r.role IN ('it','dir') OR r.project_id=sales_projects.id OR sales_projects.created_by=r.user_id OR (r.role IN ('tl','adm') AND EXISTS (SELECT 1 FROM public.user_roles s WHERE s.project_id=sales_projects.id AND public.can_read_scope(s.user_id,s.team_id,s.project_id))))));
ALTER POLICY own_create ON public.work_items WITH CHECK (owner_id=auth.uid() AND public.feature_access(feature,true) AND public.valid_owner_scope(owner_id,team_id,project_id));
ALTER POLICY own_update ON public.work_items WITH CHECK (owner_id=auth.uid() AND public.feature_access(feature,true) AND public.valid_owner_scope(owner_id,team_id,project_id));
ALTER POLICY it_lead_insert ON public.sales_leads WITH CHECK (false);
ALTER POLICY it_lead_update ON public.sales_leads USING (false) WITH CHECK (false);
REVOKE INSERT, UPDATE ON public.sales_leads FROM authenticated;
CREATE TABLE public.lead_change_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES public.sales_leads(id), requested_by uuid NOT NULL DEFAULT auth.uid(), proposed jsonb NOT NULL, reason text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','applied','rejected')), approved_by uuid, created_at timestamptz NOT NULL DEFAULT now(), applied_at timestamptz);
GRANT SELECT ON public.lead_change_requests TO authenticated;
GRANT ALL ON public.lead_change_requests TO service_role;
ALTER TABLE public.lead_change_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY request_read ON public.lead_change_requests FOR SELECT TO authenticated USING (requested_by=auth.uid() OR (public.has_role(auth.uid(),'sm') AND EXISTS (SELECT 1 FROM public.sales_leads l WHERE l.id=lead_id AND public.can_read_scope(l.owner_id,l.team_id,l.project_id))));
CREATE TABLE public.commissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL,team_id uuid,project_id uuid REFERENCES public.sales_projects(id),lead_id uuid REFERENCES public.sales_leads(id),amount numeric NOT NULL DEFAULT 0 CHECK(amount>=0),milestone text NOT NULL CHECK(milestone IN ('booking','dp','akad','bast')),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','paid')),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.commissions TO authenticated;
GRANT ALL ON public.commissions TO service_role;
ALTER TABLE public.commissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY commission_read ON public.commissions FOR SELECT TO authenticated USING(public.feature_access('portfolio',false) OR (NOT public.has_role(auth.uid(),'dm') AND public.can_read_scope(owner_id,team_id,project_id)) OR owner_id=auth.uid());
CREATE TABLE public.kpi_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL,team_id uuid,project_id uuid REFERENCES public.sales_projects(id),metric text NOT NULL,value numeric NOT NULL DEFAULT 0,logged_on date NOT NULL DEFAULT current_date,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.kpi_logs TO authenticated;
GRANT ALL ON public.kpi_logs TO service_role;
ALTER TABLE public.kpi_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY kpi_read ON public.kpi_logs FOR SELECT TO authenticated USING(public.can_read_scope(owner_id,team_id,project_id));
CREATE TABLE public.social_analytics_links(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),label text NOT NULL CHECK(length(label) BETWEEN 1 AND 100),url text NOT NULL CHECK(url LIKE 'https://%'),created_by uuid NOT NULL DEFAULT auth.uid());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.social_analytics_links TO authenticated;
GRANT ALL ON public.social_analytics_links TO service_role;
ALTER TABLE public.social_analytics_links ENABLE ROW LEVEL SECURITY;
CREATE POLICY analytics_read ON public.social_analytics_links FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'dm') OR public.has_role(auth.uid(),'sm') OR public.has_role(auth.uid(),'dir') OR public.has_role(auth.uid(),'it'));
CREATE POLICY analytics_create ON public.social_analytics_links FOR INSERT TO authenticated WITH CHECK(created_by=auth.uid() AND (public.has_role(auth.uid(),'sm') OR public.has_role(auth.uid(),'it')));
CREATE POLICY analytics_update ON public.social_analytics_links FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'sm') OR public.has_role(auth.uid(),'it')) WITH CHECK(public.has_role(auth.uid(),'sm') OR public.has_role(auth.uid(),'it'));
CREATE POLICY analytics_delete ON public.social_analytics_links FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'sm') OR public.has_role(auth.uid(),'it'));
CREATE FUNCTION public.save_sales_lead(_id uuid,_name text,_phone text,_address text,_source text,_status text,_note text DEFAULT '') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.user_roles; l public.sales_leads; result uuid; BEGIN SELECT * INTO r FROM public.user_roles WHERE user_id=auth.uid(); IF r.role IS NULL OR r.role NOT IN ('se','tl','sm') THEN RAISE EXCEPTION 'Lead access denied'; END IF; IF length(trim(_name)) NOT BETWEEN 1 AND 200 OR length(_phone) NOT BETWEEN 6 AND 30 OR length(_address) NOT BETWEEN 1 AND 500 OR _source NOT IN ('Day-to-day','Call','Chat','Posting','Indoor') OR length(_note)>2000 THEN RAISE EXCEPTION 'Invalid lead fields'; END IF; IF _id IS NULL THEN INSERT INTO public.sales_leads(nickname,prospect_name,phone,address,source,status,owner_id,team_id,project_id) VALUES(split_part(trim(_name),' ',1),trim(_name),_phone,_address,_source,_status,r.user_id,r.team_id,r.project_id) RETURNING id INTO result; ELSE SELECT * INTO l FROM public.sales_leads WHERE id=_id FOR UPDATE; IF l.id IS NULL OR NOT public.can_read_scope(l.owner_id,l.team_id,l.project_id) OR (r.role='se' AND l.owner_id<>auth.uid()) THEN RAISE EXCEPTION 'Lead access denied'; END IF; UPDATE public.sales_leads SET nickname=split_part(trim(_name),' ',1),prospect_name=trim(_name),phone=_phone,address=_address,source=_source,status=_status,verified_by=NULL,verified_at=NULL WHERE id=_id; result:=_id; END IF; SELECT * INTO l FROM public.sales_leads WHERE id=result; INSERT INTO public.sales_activities(owner_id,team_id,project_id,lead_id,kind,note) VALUES(l.owner_id,l.team_id,l.project_id,result,CASE _source WHEN 'Day-to-day' THEN 'D2D' WHEN 'Indoor' THEN 'Open table' ELSE _source END,_note); RETURN result; END $$;
REVOKE ALL ON FUNCTION public.save_sales_lead(uuid,text,text,text,text,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.save_sales_lead(uuid,text,text,text,text,text,text) TO authenticated;
CREATE FUNCTION public.verify_sales_lead(_id uuid,_value numeric) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l public.sales_leads; BEGIN IF NOT (public.has_role(auth.uid(),'tl') OR public.has_role(auth.uid(),'adm')) OR _value<0 THEN RAISE EXCEPTION 'Verification denied'; END IF; SELECT * INTO l FROM public.sales_leads WHERE id=_id FOR UPDATE; IF l.id IS NULL OR NOT public.can_read_scope(l.owner_id,l.team_id,l.project_id) THEN RAISE EXCEPTION 'Lead access denied'; END IF; UPDATE public.sales_leads SET lead_value=_value,verified_by=auth.uid(),verified_at=now() WHERE id=_id; END $$;
REVOKE ALL ON FUNCTION public.verify_sales_lead(uuid,numeric) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.verify_sales_lead(uuid,numeric) TO authenticated;
CREATE FUNCTION public.request_lead_change(_lead uuid,_proposed jsonb,_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN IF NOT public.has_role(auth.uid(),'it') OR NOT EXISTS(SELECT 1 FROM public.sales_leads WHERE id=_lead) THEN RAISE EXCEPTION 'Maintenance access denied'; END IF; IF length(trim(_reason)) NOT BETWEEN 1 AND 2000 OR jsonb_typeof(_proposed)<>'object' OR length(trim(_proposed->>'prospect_name')) NOT BETWEEN 1 AND 200 OR length(_proposed->>'phone') NOT BETWEEN 6 AND 30 OR length(_proposed->>'address') NOT BETWEEN 1 AND 500 OR (_proposed->>'source') NOT IN ('Day-to-day','Call','Chat','Posting','Indoor') OR (_proposed->>'status') NOT IN ('NA','NO','ENG','LEAD','QL','HOT','VISIT','BOOK','CV','NURTURE','LOST') OR NOT (_proposed ?& ARRAY['prospect_name','phone','address','source','status']) THEN RAISE EXCEPTION 'Invalid change request'; END IF; INSERT INTO public.lead_change_requests(lead_id,requested_by,proposed,reason) VALUES(_lead,auth.uid(),jsonb_build_object('prospect_name',trim(_proposed->>'prospect_name'),'phone',_proposed->>'phone','address',_proposed->>'address','source',_proposed->>'source','status',_proposed->>'status'),trim(_reason)) RETURNING id INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.request_lead_change(uuid,jsonb,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.request_lead_change(uuid,jsonb,text) TO authenticated;
CREATE FUNCTION public.review_lead_change(_request uuid,_approve boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'sm') THEN RAISE EXCEPTION 'SM approval required'; END IF; UPDATE public.lead_change_requests q SET status=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END,approved_by=auth.uid() WHERE q.id=_request AND q.status='pending' AND EXISTS(SELECT 1 FROM public.sales_leads l WHERE l.id=q.lead_id AND public.can_read_scope(l.owner_id,l.team_id,l.project_id)); IF NOT FOUND THEN RAISE EXCEPTION 'Request unavailable'; END IF; END $$;
REVOKE ALL ON FUNCTION public.review_lead_change(uuid,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.review_lead_change(uuid,boolean) TO authenticated;
CREATE FUNCTION public.apply_lead_change(_request uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.lead_change_requests; p jsonb; BEGIN IF NOT public.has_role(auth.uid(),'it') THEN RAISE EXCEPTION 'Maintenance access denied'; END IF; SELECT * INTO q FROM public.lead_change_requests WHERE id=_request AND requested_by=auth.uid() AND status='approved' FOR UPDATE; IF q.id IS NULL OR NOT public.has_role(q.approved_by,'sm') THEN RAISE EXCEPTION 'SM approval required'; END IF; IF NOT EXISTS(SELECT 1 FROM public.sales_leads l JOIN public.user_roles r ON r.user_id=q.approved_by WHERE l.id=q.lead_id AND (r.project_id=l.project_id OR EXISTS(SELECT 1 FROM public.sales_projects p WHERE p.id=l.project_id AND p.created_by=r.user_id))) THEN RAISE EXCEPTION 'Approver scope changed'; END IF; p:=q.proposed; UPDATE public.sales_leads SET nickname=split_part(p->>'prospect_name',' ',1),prospect_name=p->>'prospect_name',phone=p->>'phone',address=p->>'address',source=p->>'source',status=p->>'status',verified_by=NULL,verified_at=NULL WHERE id=q.lead_id; UPDATE public.lead_change_requests SET status='applied',applied_at=now() WHERE id=q.id; END $$;
REVOKE ALL ON FUNCTION public.apply_lead_change(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.apply_lead_change(uuid) TO authenticated;
CREATE TRIGGER audit_lead AFTER INSERT OR UPDATE ON public.sales_leads FOR EACH ROW EXECUTE FUNCTION public.audit_revision_changes();
CREATE TRIGGER audit_lead_change AFTER INSERT OR UPDATE ON public.lead_change_requests FOR EACH ROW EXECUTE FUNCTION public.audit_revision_changes();
CREATE TRIGGER audit_analytics AFTER INSERT OR UPDATE ON public.social_analytics_links FOR EACH ROW EXECUTE FUNCTION public.audit_revision_changes();